 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * Load a definitions file: one definition per line, blank lines and `#` lines ignored.
 * @param {string} path - the path to the definitions file.
 * @returns {Map<string, string>} normalized label to url.
 * @throws {Error} formatted for direct display, on a bad line, a duplicate label, or a read failure.
 */
export function loadDefinitionsFile(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    throw new Error(`cannot read definitions ${path}`)
  }
  const lines = splitLines(text)
