    const match = DEFINITION.exec(trimmed)
    if (match === null) throw new Error(`${path}: line ${number}: expected [label]: <url>`)
    const label = normalizeLabel(match[1])
    if (definitions.has(label)) throw new Error(`${path}: line ${number}: label ${label} is defined twice`)
    definitions.set(label, match[2])
  }
  return definitions
}

