export function parse(lines, fileDefinitions = new Map()) {
  const out = []
  const definitions = new Map()
  let paragraph = []
  let listRoot
  let levels
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (listRoot !== undefined) {
      out.push({ kind: 'list', items: listRoot })
      listRoot = undefined
      levels = undefined
    }
