      let target
      if (capped <= levels.length - 1) {
        levels.length = capped + 1
        target = levels[capped]
      } else {
        const parentArray = levels[levels.length - 1]
        const parentItem = parentArray[parentArray.length - 1]
        parentItem.children = []
        levels.push(parentItem.children)
        target = parentItem.children
      }
